ps://docs.github.com/github/creating-cloning-and-archiving-repositories/creating-a-repository-on-github/about-citation-files","actionsOnboardingTip":null},"truncated":false,"viewable":true,"workflowRedirectUrl":null},"copilotInfo":null,"copilotAccessAllowed":false,"copilotSpacesEnabled":false,"modelsAccessAllowed":false,"modelsRepoIntegrationEnabled":false,"isMarketplaceEnabled":true},"codeViewBlobLayoutRoute.StyledBlob":{"rawLines":["#!/bin/sh","set -eu","","GKI_ROOT=\"$(pwd)\"","","display_usage() {","    echo \"Usage: $0 [--cleanup | \u003ccommit-or-tag\u003e]\"","    echo \"  --cleanup            Clean up modifications made by this script.\"","    echo \"  -h, --help           Show this help.\"","    echo \"  (no args)            Setup Baseband-guard to latest main.\"","}","","initialize_variables() {","    if [ -d \"$GKI_ROOT/security\" ]; then","        SECURITY_DIR=\"$GKI_ROOT/security\"","    elif [ -d \"$GKI_ROOT/common/security\" ]; then","        SECURITY_DIR=\"$GKI_ROOT/common/security\"","    else","        echo '[ERROR] \"security/\" directory not found.'","        exit 127","    fi","","    if [ -d \"$GKI_ROOT/include\" ]; then","        INCLUDE_DIR=\"$GKI_ROOT/include\"","    elif [ -d \"$GKI_ROOT/common/security\" ]; then","        INCLUDE_DIR=\"$GKI_ROOT/common/include\"","    else","        echo '[ERROR] \"include/\" directory not found.'","        exit 127","    fi","    ","    SECURITY_MAKEFILE=\"$SECURITY_DIR/Makefile\"","    SECURITY_KCONFIG=\"$SECURITY_DIR/Kconfig\"","    BBG_DIR=\"$GKI_ROOT/Baseband-guard\"","    BBG_SYMLINK=\"$SECURITY_DIR/baseband-guard\"","    BBG_REPO=\"https://github.com/vc-teahouse/Baseband-guard\"","    SELINUX_MAKEFILE=\"$SECURITY_DIR/selinux/Makefile\"","    SELINUX_OBJSEC=\"$SECURITY_DIR/selinux/include/objsec.h\"","    PATCH_FILE=\"$BBG_DIR/sepatch.txt\"","    LSM_HOOKS_H=\"$INCLUDE_DIR/linux/lsm_hooks.h\"","}","","# Revert changes","perform_cleanup() {","    echo \"[+] Cleaning up\"","    [ -L \"$BBG_SYMLINK\" ] \u0026\u0026 rm -f \"$BBG_SYMLINK\" \u0026\u0026 echo \" - symlink removed\"","    if [ -f \"$SECURITY_MAKEFILE\" ] \u0026\u0026 grep -q 'baseband-guard' \"$SECURITY_MAKEFILE\"; then","        sed -i '/baseband-guard/d' \"$SECURITY_MAKEFILE\"; echo \" - Makefile reverted\"","    fi","    if [ -f \"$SECURITY_KCONFIG\" ] \u0026\u0026 grep -q 'security/baseband-guard/Kconfig' \"$SECURITY_KCONFIG\"; then","        sed -i '/security\\/baseband-guard\\/Kconfig/d' \"$SECURITY_KCONFIG\"; echo \" - Kconfig reverted\"","    fi","    if [ -f \"${SELINUX_MAKEFILE}.bak\" ]; then","        rm -f $SELINUX_MAKEFILE \u0026\u0026 mv \"${SELINUX_MAKEFILE}.bak\" \"$SELINUX_MAKEFILE\"; echo \" - Selinux Makefile reverted\"","    fi","    if [ -f \"${SELINUX_OBJSEC}.bak\" ]; then","        rm -f $SELINUX_OBJSEC \u0026\u0026 mv \"${SELINUX_OBJSEC}.bak\" \"$SELINUX_OBJSEC\"; echo \" - Selinux objsec.h reverted\"","    fi","    [ -d \"$BBG_DIR\" ] \u0026\u0026 rm -rf \"$BBG_DIR\" \u0026\u0026 echo \" - Baseband-guard dir deleted\"","}","","# Setup / update","setup_baseband_guard() {","    ref=\"${1:-}\"   # optional commit or tag","    echo \"[+] Setting up Baseband-guard\"","","    if [ -d \"$BBG_DIR/.git\" ]; then","        ( cd \"$BBG_DIR\"","          git fetch origin +refs/heads/*:refs/remotes/origin/* \u003e/dev/null 2\u003e\u00261 || true","          if [ -n \"$ref\" ]; then","              git fetch origin \"$ref\" || true","              git checkout -q \"$ref\"","          else","              git checkout -q main || git checkout -q master || true","              git pull --ff-only || true","          fi","        )","    else","        if [ -n \"$ref\" ]; then","            git clone --branch \"$ref\" \"$BBG_REPO\" \"$BBG_DIR\"","        else","            git clone \"$BBG_REPO\" \"$BBG_DIR\"","        fi","        echo \" - repo ready\"","    fi","","    # Symlink security/baseband-guard -\u003e ../Baseband-guard","    cd \"$SECURITY_DIR\"","    # prefer relative path; fall back to absolute if realpath --relative-to not available","    if command -v realpath \u003e/dev/null 2\u003e\u00261; then","        rel=\"$(realpath --relative-to=\"$SECURITY_DIR\" \"$BBG_DIR\" 2\u003e/dev/null || true)\"","    else","        rel=\"$BBG_DIR\"","    fi","    ln -sfn \"$rel\" \"$BBG_SYMLINK\"","    echo \" - symlink created\"","","    # Makefile entry (idempotent)","    if ! grep -q 'baseband-guard/baseband_guard.o' \"$SECURITY_MAKEFILE\"; then","        printf '\\nobj-$(CONFIG_BBG) += baseband-guard/\\n' \u003e\u003e \"$SECURITY_MAKEFILE\"","        echo \" - Makefile updated\"","    fi","","    # Kconfig source (insert before last endmenu; fallback append)","    if ! grep -q 'security/baseband-guard/Kconfig' \"$SECURITY_KCONFIG\"; then","        if grep -n '^endmenu[[:space:]]*$' \"$SECURITY_KCONFIG\" \u003e/dev/null 2\u003e\u00261; then","            # insert before LAST endmenu","            awk '","              { a[NR]=$0 } END{","                last=0; for(i=1;i\u003c=NR;i++) if(a[i] ~ /^endmenu[[:space:]]*$/) last=i;","                for(i=1;i\u003c=NR;i++){","                  if(i==last) print \"source \\\"security/baseband-guard/Kconfig\\\"\";","                  print a[i];","                }","              }' \"$SECURITY_KCONFIG\" \u003e \"$SECURITY_KCONFIG.tmp\" \u0026\u0026 mv \"$SECURITY_KCONFIG.tmp\" \"$SECURITY_KCONFIG\"","        else","            printf '\\nsource \"security/baseband-guard/Kconfig\"\\n' \u003e\u003e \"$SECURITY_KCONFIG\"","        fi","        echo \" - Kconfig updated\"","    fi","    ","    # nongki compatible","","    if [ ! -f \"$LSM_HOOKS_H\" ]; then","        echo \"Error: Cannot find lsm_hooks.h at $LSM_HOOKS_H\"","        exit 1","    fi","","    if ! grep -q \"#define DEFINE_LSM(lsm)\" \"$LSM_HOOKS_H\"; then","        echo \"Modern LSM infrastructure not detected (pre-5.1 kernel style).\"","        echo \"Applying Selinux patch for BBG...\"","","        if [ ! -f \"$SELINUX_MAKEFILE\" ]; then","            echo \"Error: '$SELINUX_MAKEFILE' not found!\"","            exit 1","        fi","    ","        if [ ! -f \"$SELINUX_OBJSEC\" ]; then","            echo \"Error: '$SELINUX_OBJSEC' not found!\"","            exit 1","        fi","","        if [ ! -f \"$PATCH_FILE\" ]; then","            echo \"Error: patching code '$PATCH_FILE' not found! \"","            exit 1","        fi","","        cp $SELINUX_MAKEFILE ${SELINUX_MAKEFILE}.bak","        cp $SELINUX_OBJSEC ${SELINUX_OBJSEC}.bak","        cat \"$PATCH_FILE\" \u003e\u003e \"$SELINUX_MAKEFILE\"","        sed -i '/#include \"avc.h\"/a #ifndef BBG_USE_DEFINE_LSM\\n#include \"bbg_tracing.h\"\\n#endif' \"$SELINUX_OBJSEC\"","        sed -i '/u32 sockcreate_sid[;]*/a #ifndef BBG_USE_DEFINE_LSM\\n\\tstruct bbg_cred_security_struct  bbg_cred; /* bbg cred security */\\n#endif' \"$SELINUX_OBJSEC\"","        ln -sfn \"../../$rel/tracing/tracing.h\" \"$SECURITY_DIR/selinux/include/bbg_tracing.h\" # symlink tracing.h","        echo \"Selinux patching done!\"","    else","        echo \"Modern LSM infrastructure detected (GKI/Modern Kernel). Skipping Selinux patch.\"","        echo \"BBG will use standard LSM blob management.\"","    fi","","    echo \"[+] Done.\"","}","","show_config_lsm_notice() {","    if awk '/^[[:space:]]*config[[:space:]]+LSM$/ { found=1; exit } END { exit !found }' $SECURITY_KCONFIG; then","        echo \"\"","        echo \"Please manually set your defconfig, select one append to your defconfig:\"","        echo \"\"","        awk '","        /^[[:space:]]*config[[:space:]]+LSM$/ { in_lsm=1; next }","        in_lsm \u0026\u0026 /^[[:space:]]*config[[:space:]]+/ { exit }","        in_lsm \u0026\u0026 /^[[:space:]]*default/ {","            match($0, /\"([^\"]+)\"/, m)","            if ($0 ~ /if[[:space:]]+/) {","                sub(/.*if[[:space:]]+/, \"\", $0)","                cond = $0","                print \"if \" cond \" enabled:\"","            } else {","                print \"else:\"","    